#![allow(unused_imports)]
use vstd::prelude::*;
use vstd::vec::Vec;

verus! {

    /// Concatenate two nonempty integer slices.
    ///
    /// # Parameters
    /// - `x`: a nonempty slice of `i32`
    /// - `y`: a nonempty slice of `i32`
    ///
    /// # Returns
    /// A `Vec<i32>` whose abstract sequence `res@` is `x@ ++ y@`.
    fn single(x: &[i32], y: &[i32]) -> Vec<i32>
        requires x.len() > 0
        requires y.len() > 0
        ensures |res: Vec<i32>| res@ == x@ + y@
    {
        let mut res: Vec<i32> = Vec::new();
        // Pre‐allocate so we don't have to worry about re‐allocations
        res.reserve(x.len() + y.len());

        // First, push all of x
        let mut i = 0;
        while i < x.len()
            invariant i <= x.len()
            // res@ is exactly the prefix of x@ of length i
            invariant res@ == Seq::slice(x@, 0, i)
        {
            res.push(x[i]);
            i += 1;
        }

        // Next, push all of y
        let mut j = 0;
        while j < y.len()
            invariant j <= y.len()
            // res@ is exactly x@ ++ the prefix of y@ of length j
            invariant res@ == x@ + Seq::slice(y@, 0, j)
        {
            res.push(y[j]);
            j += 1;
        }

        res
    }

} // verus!